<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { api, type Account } from './api'
import { projectOptions } from './project-options'
import ProjectPeopleSelect from './ProjectPeopleSelect.vue'
import type { LiveProject, ProjectPerson, ProjectTask, ProjectUnit } from './project-api'
const props=defineProps<{project?:LiveProject|null;taskEdit?:{project:LiveProject;task?:ProjectTask;assigneeId?:string};people:ProjectPerson[];account:Account;saveProject:(data:unknown)=>Promise<void>;saveTask:(data:unknown)=>Promise<void>;deleteTask:()=>Promise<void>}>()
const emit=defineEmits<{close:[]}>()
const busy=ref(false),error=ref(''),dialog=ref<HTMLElement>()
const p=props.project,t=props.taskEdit?.task
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const types=computed(()=>projectOptions.value.filter(o=>o.scope==='types'))
const project=ref({title:p?.title||'',code:p?.code||'',type:p?.type||types.value.find(o=>o.name==='科研课题')?.name||types.value[0]?.name||'',ownerId:p?.ownerId||props.account.id,studentOwnerId:p?.studentOwnerId||'',unit:p?.unit||'',sponsor:p?.sponsor||'',phase:p?.phase||'',summary:p?.summary||'',start:p?.start||'',end:p?.end||'',progress:p?.progress||0,status:p?.status||'正常推进',lifecycle:p?.lifecycle||'未开始',revision:p?.revision,tags:p?.tags.join('、')||''})
const memberships=ref(p?.members.filter(m=>m.role!=='项目负责人'&&m.role!=='学生负责人').map(m=>({userId:m.userId,role:m.role}))||[])
const units=ref<ProjectUnit[]>(p?.units.map(u=>({...u}))||[])
const contactDirectory=ref<{units:{id:string;name:string}[];people:{id:string;name:string;organizationId:string|null}[]}>({units:[],people:[]})
const contactsLoading=ref(!props.taskEdit)
function unitContacts(name:string){const id=contactDirectory.value.units.find(unit=>unit.name===name)?.id;return id?contactDirectory.value.people.filter(person=>person.organizationId===id):[]}
async function loadContacts(){try{contactDirectory.value=await api('/organization')}catch(e){error.value=(e as Error).message}finally{contactsLoading.value=false}}
const workdayOptions=Array.from({length:20},(_,index)=>(index+1)/2)
const task=ref({spentDays:t?.spentDays??null,taskType:t?.taskType||'',participantIds:t?.participantIds?.slice()||[],description:t?.description||'',title:t?.title||'',assigneeId:t?.assigneeId||props.taskEdit?.assigneeId||props.taskEdit?.project.ownerId||'',start:t?.start||props.taskEdit?.project.start||today,due:t?.due||props.taskEdit?.project.end||today,parentId:t?.parentId||'',dependsOn:t?.dependsOn||'',state:t?.state||'待开始',progress:t?.progress||0,revision:t?.revision})
const manager=computed(()=>props.taskEdit?.project.canManageTasks??props.taskEdit?.project.canManage)
const confirmingDelete=ref(false)
async function removeTask(){busy.value=true;error.value='';try{await props.deleteTask()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const taskMilestones=ref(t?.milestoneIds?.slice()||props.taskEdit?.project.milestones.filter(m=>m.taskIds.includes(t?.id||'')).map(m=>m.id)||[])
const milestoneRevisions=Object.fromEntries((props.taskEdit?.project.milestones||[]).map(m=>[m.id,m.revision]))
const eligible=computed(()=>props.people.filter(person=>person.active||p?.members.some(m=>m.userId===person.id)))
const eligibleStudents=computed(()=>eligible.value.filter(person=>person.role==='学生'||person.id===project.value.studentOwnerId))
const relations=computed(()=>props.taskEdit?.project.tasks.filter(item=>item.id!==t?.id)||[])
const admin=['系统管理员'].includes(props.account.role)
function selectMembers(ids:string[]){memberships.value=ids.filter(id=>id!==project.value.ownerId).map(id=>memberships.value.find(m=>m.userId===id)||{userId:id,role:'项目成员'})}
function changeState(){if(task.value.state==='已完成')task.value.progress=100;else if(task.value.state==='待开始')task.value.progress=0}
async function submit(){busy.value=true;error.value='';try{if(props.taskEdit)await props.saveTask(manager.value?{...task.value,milestoneIds:taskMilestones.value,milestoneRevisions}:{revision:task.value.revision,state:task.value.state,progress:task.value.progress,spentDays:task.value.spentDays,description:task.value.description});else await props.saveProject({...project.value,tags:project.value.tags.split(/[、,，]/).map(s=>s.trim()).filter(Boolean),members:memberships.value.filter(m=>m.userId!==project.value.ownerId),units:units.value.filter(unit=>unit.name.trim()||unit.contact.trim()||unit.duty.trim())})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
let previous:HTMLElement|null=null
function keydown(event:KeyboardEvent){if(event.key==='Escape'&&!busy.value){event.preventDefault();emit('close')}if(event.key==='Tab'){const nodes=Array.from(dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)')||[]);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}}
onMounted(()=>{previous=document.activeElement as HTMLElement;dialog.value?.querySelector<HTMLElement>('input,button')?.focus();document.addEventListener('keydown',keydown);if(!props.taskEdit)void loadContacts()})
onUnmounted(()=>{document.removeEventListener('keydown',keydown);previous?.focus()})
</script>
<template>
  <div class="pm-modal"><form ref="dialog" class="pm-form" role="dialog" aria-modal="true" aria-labelledby="editor-title" @submit.prevent="submit"><div class="pm-form-header"><h2 id="editor-title">{{ taskEdit?(t?'更新任务':'添加任务'):(p?'编辑项目与成员':'新建项目') }}</h2><button type="button" :disabled="busy" aria-label="关闭编辑" @click="emit('close')">关闭</button></div>
    <template v-if="!taskEdit"><div class="pm-form-grid"><label>项目名称<input v-model.trim="project.title" required maxlength="150"></label><label>项目编号<input placeholder="选填" v-model.trim="project.code" maxlength="80"></label><label>项目类型<select aria-label="项目类型" v-model="project.type"><option v-for="option in types" :key="option.id" :value="option.name">{{ option.name }}</option><option v-if="project.type&&!types.some(o=>o.name===project.type)" :value="project.type">{{ project.type }}</option></select></label><label>项目负责人<select aria-label="项目负责人" v-model="project.ownerId" :disabled="!admin"><option v-for="person in eligible" :key="person.id" :value="person.id">{{ person.name }}{{ person.active?'':'（已停用）' }}</option></select></label><label>学生负责人<select aria-label="学生负责人" v-model="project.studentOwnerId"><option value="">未选择</option><option v-for="person in eligibleStudents" :key="person.id" :value="person.id" :disabled="!person.active&&person.id!==p?.studentOwnerId">{{ person.name }}{{ person.active?'':'（已停用）' }}</option></select></label><label>牵头单位<select aria-label="牵头单位" v-model="project.unit"><option value="">未选择</option><option v-for="option in projectOptions.filter(o=>o.scope==='units')" :key="option.id" :value="option.name">{{ option.name }}</option><option v-if="project.unit && !projectOptions.some(o=>o.scope==='units' && o.name===project.unit)" :value="project.unit">{{ project.unit }}</option></select></label><label>项目来源<select aria-label="项目来源" v-model="project.sponsor"><option value="">未选择</option><option v-for="option in projectOptions.filter(o=>o.scope==='sources')" :key="option.id" :value="option.name">{{ option.name }}</option><option v-if="project.sponsor && !projectOptions.some(o=>o.scope==='sources' && o.name===project.sponsor)" :value="project.sponsor">{{ project.sponsor }}</option></select></label><label>开始日期<input v-model="project.start" type="date"></label><label>截止日期<input v-model="project.end" type="date" :min="project.start"></label><label>当前阶段<input v-model.trim="project.phase" maxlength="100"></label><label>项目进度（%）<input v-model.number="project.progress" type="number" min="0" max="100" step="1"></label><label>项目状态<select v-model="project.lifecycle"><option v-for="value in ['未开始','进行中','已暂停','已取消','已完成']" :key="value">{{ value }}</option></select></label><label>健康状态<select v-model="project.status"><option v-for="value in ['正常推进','需要关注','待协调']" :key="value">{{ value }}</option></select></label></div><label>标签（用顿号分隔）<input v-model="project.tags" maxlength="2000"></label><label>项目简介<textarea v-model="project.summary" maxlength="10000"></textarea></label>
    <fieldset><legend>参与人员</legend><p class="muted">可下拉多选；项目负责人和学生负责人自动参与，任务执行人须为参与人员。</p><ProjectPeopleSelect :people="eligible" :owner-id="project.ownerId" :student-owner-id="project.studentOwnerId" :model-value="memberships.map(m=>m.userId)" @update:model-value="selectMembers"/><div v-for="person in eligible.filter(person=>person.id!==project.ownerId && person.id!==project.studentOwnerId && memberships.some(m=>m.userId===person.id))" :key="person.id" class="pm-member"><span>{{ person.name }}{{ person.active?'':'（已停用）' }}</span><select v-model="memberships.find(m=>m.userId===person.id)!.role" :aria-label="`${person.name}的项目角色`"><option>项目成员</option><option>项目协调人</option></select></div></fieldset>
    <fieldset><legend>参与单位</legend><div v-for="(unit,index) in units" :key="index" class="pm-unit"><label>单位名称<select aria-label="单位名称" v-model="unit.name" @change="unit.contact=''"><option value="">未选择</option><option v-for="option in projectOptions.filter(o=>o.scope==='participantUnits')" :key="option.id" :value="option.name">{{ option.name }}</option><option v-if="unit.name && !projectOptions.some(o=>o.scope==='participantUnits' && o.name===unit.name)" :value="unit.name">{{ unit.name }}</option></select></label><label>单位角色<select v-model="unit.role"><option>牵头单位</option><option>协作单位</option><option>执行团队</option></select></label><label>联系人<select aria-label="联系人" v-model="unit.contact" :disabled="contactsLoading||!unit.name"><option value="">{{ contactsLoading?'加载人员中…':!unit.name?'请先选择单位':unitContacts(unit.name).length?'未选择':'该单位暂无人员' }}</option><option v-for="person in unitContacts(unit.name)" :key="person.id" :value="person.name">{{ person.name }}</option><option v-if="!contactsLoading&&unit.contact&&!unitContacts(unit.name).some(person=>person.name===unit.contact)" :value="unit.contact" disabled>{{ unit.contact }}（原联系人，已不在该单位）</option></select></label><label>单位职责<input v-model.trim="unit.duty" maxlength="1000"></label><button type="button" @click="units.splice(index,1)">移除单位</button></div><button type="button" @click="units.push({name:'',role:'协作单位',contact:'',duty:''})">添加参与单位</button></fieldset></template>
    <template v-else><div v-if="manager" class="pm-form-grid"><label>任务名称<input v-model.trim="task.title" required maxlength="150"></label><label>任务类型<select v-model="task.taskType" aria-label="任务类型"><option value="">未选择</option><option v-for="option in projectOptions.filter(o=>o.scope==='taskTypes')" :key="option.id" :value="option.name">{{ option.name }}</option></select></label><label>负责人<select v-model="task.assigneeId" required><option v-for="member in taskEdit.project.members" :key="member.userId" :value="member.userId" :disabled="member.active===false&&member.userId!==t?.assigneeId">{{ member.name }}{{ member.active===false?'（已停用）':'' }}</option></select></label><div class="task-participants"><span>参与人员（选填，可多选）</span><ProjectPeopleSelect :people="taskEdit.project.members.map(m=>({id:m.userId,name:m.name,active:m.active!==false}))" v-model="task.participantIds" owner-id="" /></div><label>任务开始日期<input v-model="task.start" type="date" :min="taskEdit.project.start" :max="taskEdit.project.end" required></label><label>任务截止日期<input v-model="task.due" type="date" :min="task.start" :max="taskEdit.project.end" required></label><label>父任务<select v-model="task.parentId"><option value="">无</option><option v-for="item in relations" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><label>前置任务<select v-model="task.dependsOn"><option value="">无</option><option v-for="item in relations" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><div class="task-milestone-field"><span>里程碑（选填，可多选）</span><details class="task-milestone-select"><summary aria-label="任务里程碑">{{ taskMilestones.length?taskEdit.project.milestones.filter(m=>taskMilestones.includes(m.id)).map(m=>m.title).join('、'):'未关联里程碑' }}</summary><div class="task-milestone-options"><label v-for="milestone in taskEdit.project.milestones" :key="milestone.id"><input type="checkbox" v-model="taskMilestones" :value="milestone.id">{{ milestone.title }} · {{ milestone.state }}</label><p v-if="!taskEdit.project.milestones.length" class="muted">暂无里程碑，请先在项目里程碑栏目创建。</p><button type="button" @click="taskMilestones=[]">清除选择</button></div></details></div></div><div v-else><p>{{ task.title }} · {{ taskEdit.project.title }}</p><p class="muted">任务类型：{{ task.taskType||'未选择' }}</p><p class="muted">参与人员：{{ t?.participants?.map(person=>person.name).join('、')||'未选择' }}</p><p class="muted">里程碑：{{ taskEdit.project.milestones.filter(m=>taskMilestones.includes(m.id)).map(m=>m.title).join('、')||'未关联' }}</p></div><div class="pm-form-grid"><label>任务状态<select v-model="task.state" @change="changeState"><option v-for="value in ['待开始','进行中','测试中','待反馈','已完成']" :key="value">{{ value }}</option></select></label><label>任务进度（%）<input v-model.number="task.progress" type="number" min="0" max="100" step="1" :readonly="['待开始','已完成'].includes(task.state)" required></label></div><label>花费工日<select v-model="task.spentDays" aria-label="花费工日"><option :value="null">未填写</option><option v-for="days in workdayOptions" :key="days" :value="days">{{ days.toFixed(1) }}</option></select></label><label>任务描述<textarea v-model="task.description" maxlength="5000" rows="3" placeholder="选填：填写任务内容、要求或预期成果"></textarea></label></template>
    <div v-if="taskEdit&&t&&manager"><button v-if="!confirmingDelete" type="button" :disabled="busy" @click="confirmingDelete=true">删除任务</button><template v-else><p>确认删除“{{ t.title }}”？该任务的工日将从统计中移除，历史记录和附件保留。</p><button type="button" :disabled="busy" @click="confirmingDelete=false">取消删除</button> <button type="button" :disabled="busy" @click="removeTask">确认删除任务</button></template></div>
    <p v-if="error" role="alert" class="pm-error">{{ error }}</p><p v-if="error.includes('刷新')" class="muted">请关闭编辑并刷新页面，核对最新内容后重新编辑。</p><div class="pm-form-actions"><button type="button" :disabled="busy" @click="emit('close')">取消</button><button class="pm-primary" :disabled="busy">{{ busy?'保存中…':'保存' }}</button></div>
  </form></div>
</template>
<style scoped>.task-milestone-field{display:grid;gap:5px;align-content:start}.task-milestone-select{border:1px solid var(--line);border-radius:5px;background:white;padding:8px}.task-milestone-select summary{cursor:pointer;overflow-wrap:anywhere}.task-milestone-options{display:grid;gap:7px;max-height:210px;overflow:auto;padding-top:10px}.task-milestone-options label{display:flex;gap:7px;align-items:center;margin:0}.task-milestone-options input{width:auto;margin:0}.task-milestone-options button{justify-self:start}</style>
